            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});state.service_assignment.waiting=false;state.service_assignment.auto_assign=true;state.service_assignment.can_assign=false;apply();var p=preview.GetComponent<PythonServiceAssignmentPanel>();client.ToggleAutomatic();if(!client.Automatic)throw new Exception("Automatic progress did not start");p.Open();if(client.Automatic)throw new Exception("Opening assignment did not pause progress");p.Close();client.ToggleAutomatic();state.service_assignment.waiting=true;state.service_assignment.auto_assign=false;state.service_assignment.can_assign=true;typeof(PythonStateClient).GetField("pending",f).SetValue(client,new PythonShiftCommand{kind="advance_business"});apply();if(p.panel.activeSelf || client.Automatic)throw new Exception("Busy waiting did not pause/defer dialog");typeof(PythonStateClient).GetField("pending",f).SetValue(client,null);apply();if(!p.panel.activeSelf || !p.proceed.interactable || client.CanProgressBusiness)throw new Exception("Manual waiting did not stop/open");Capture(preview,"Logs/ServiceAssignment.png");p.Close();Capture(preview,"Logs/ServiceAssignmentWaiting.png");apply();if(p.panel.activeSelf)throw new Exception("Waiting panel reopened");var list=preview.GetComponent<PythonEventListPanel>();list.Open();if(list.entries.Length!=25 || !list.entries[23].interactable)throw new Exception("Assignment entry missing");list.ServiceAssignment();if(list.panel.activeSelf || !p.panel.activeSelf)throw new Exception("Assignment navigation failed");p.SelectCat(1);if(p.proceed.interactable || !p.details.text.Contains("出勤していません"))throw new Exception("Resting cat enabled");p.SelectCat(0);p.SelectSeat(1);if(p.proceed.interactable)throw new Exception("Occupied seat enabled");p.SelectSeat(0);p.Proceed();var request=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);if(request==null || request.kind!="assign_service" || request.custome